select

from survey_teach_reward_list

  delete_flag=0

    and id=#{id}


    and list_name like '%${listName}%'


    and teacher_num=#{teacherNum}


    and student_num=#{studentNum}


    and teacher_reward=#{teacherReward}


    and state=#{state}


    and create_time=#{createTime}


    and craete_by=#{craeteBy}


    and update_time=#{updateTime}


    and update_by=#{updateBy}


    and return_desc=#{returnDesc}


    and approval_time=#{approvalTime}
